// 续办签发只追加政治来源；真正劳动递减与赈济支付继续走原S3/S5事务。
#include "political_governance_continuation_detail.hpp"
namespace hanmo::resident {
namespace {
// Quote只固定用户选择及真实候选身份，commit仍重做完整权限，不信任Quote自带载荷。
bool same_identity(const WorldIdentity& a,const WorldIdentity& b){return a.world_id==b.world_id&&a.execution_epoch==b.execution_epoch&&a.revision==b.revision&&a.tick==b.tick;}
bool same_command(const PoliticalContinueGovernance& a,const PoliticalContinueGovernance& b){return a.authority.organization_id==b.authority.organization_id&&a.authority.office_id==b.authority.office_id&&a.authority.actor_id==b.authority.actor_id&&a.authority.authority_epoch==b.authority.authority_epoch&&a.task_id==b.task_id&&a.registration_fact_id==b.registration_fact_id&&a.approval_fact_id==b.approval_fact_id&&a.decision_fact_id==b.decision_fact_id;}
}
Outcome<PoliticalGovernanceContinuationQuote> preview_political_governance_continuation(const PoliticalGovernanceContinuationContext& x,const StableId& actor,const PoliticalContinueGovernance& command){
 using namespace governance_continue_detail;const auto fail=[&](const StableId& code){return Outcome<PoliticalGovernanceContinuationQuote>{false,{},common_failure(code,command.task_id).error};};
 if(x.phase)return fail("GovernanceContinuationRequiresCommittedClock");if(command.authority.actor_id!=actor)return fail("PoliticalCommandActorMismatch");auto valid=validate_political_governance_continuations(x);if(!valid.ok)return {false,{},valid.error};
 auto raw=x.tasks.governance_task_source(command.task_id);if(!raw.ok)return {false,{},raw.error};auto a=x.original_authority.governance_authority_approval(raw.value.acceptance.authority_source_fact_id);if(!a.ok)return {false,{},a.error};auto t=task_source(x,command.task_id,a.value,x.common.tick(),{});if(!t.ok)return {false,{},t.error};
 auto original=x.original_authority.governance_continuity(a.value.authority_fact_id,a.value.executor_actor_id);if(!original.ok)return {false,{},original.error};if(original.value.kind!=GovernanceContinuityKind::needs_reassignment||(original.value.code!="GovernanceControlOrAssetsChanged"&&original.value.code!="GovernanceOfficeVacant"))return fail("GovernanceContinuationNotRequired");
 auto e=x.takeover.find_political_responsibility_for_execution({PoliticalResponsibilityKind::relief_contract,t.value.acceptance.contract_id,{},{}},x.common.state().identity);if(!e.ok)return {false,{},e.error};if(!e.value)return fail("GovernanceContinuationTakeoverUnavailable");valid=execution_source(x,a.value,t.value.acceptance,*e.value);if(!valid.ok)return {false,{},valid.error};const auto& decision=*e.value->decision;
 if(command.registration_fact_id!=e.value->registration_fact_id||command.approval_fact_id!=decision.takeover_fact_id||command.decision_fact_id!=decision.decision_fact_id||command.authority.organization_id!=e.value->registration.successor_organization_id)return fail("StaleGovernanceContinuationDecision");
 for(const auto& row:x.state.continuations.rows())if(row.second.task_id==command.task_id&&row.second.decision_fact_id==command.decision_fact_id)return fail("GovernanceContinuationAlreadyRecorded");
 valid=current_assets(x,a.value,command.authority.organization_id);if(!valid.ok)return {false,{},valid.error};auto grant=current_grant(x,a.value,command.authority);if(!grant.ok)return {false,{},grant.error};valid=alive_before(x,a.value.executor_actor_id,x.common.tick(),{});if(!valid.ok)return {false,{},valid.error};
 const auto& accepted=t.value.acceptance;PoliticalGovernanceContinuation r;r.task_id=accepted.task_id;r.acceptance_fact_id=accepted.fact_id;r.authority_fact_id=a.value.authority_fact_id;r.contract_id=accepted.contract_id;r.executor_actor_id=accepted.executor_actor_id;r.jurisdiction_id=a.value.jurisdiction_id;r.site_id=a.value.site_id;r.original_organization_id=a.value.organization_id;r.public_wallet_id=a.value.public_wallet_id;r.public_inventory_id=a.value.public_inventory_id;r.registration_fact_id=e.value->registration_fact_id;r.approval_fact_id=decision.takeover_fact_id;r.decision_fact_id=decision.decision_fact_id;r.occupation_fact_id=e.value->registration.occupation_fact_id;r.grant_id=grant.value;r.authority=command.authority;r.tick=x.common.tick();
 return {true,{x.common.state().identity,command,std::move(r)},{}};
}
// 原Common与新账必须由调用方同一保存点覆盖；全部预检后才分配一个真实来源ID。
Outcome<StableId> apply_political_governance_continuation_in_candidate(CommonStore& common,PoliticalGovernanceContinuationState& state,const PoliticalGovernanceContinuationContext& x,const StableId& actor,const PoliticalContinueGovernance& command,const PoliticalGovernanceContinuationQuote& quote){
 if(&common!=&x.common||&state!=&x.state)return {false,{},common_failure("GovernanceContinuationWrongCandidate").error};if(!same_identity(quote.identity,common.state().identity)||!same_command(quote.command,command))return {false,{},common_failure("StaleGovernanceContinuationQuote").error};
 auto current=preview_political_governance_continuation(x,actor,command);if(!current.ok)return {false,{},current.error};auto id=common.next_id(political_governance_continue_prefix);if(!id.ok)return id;auto r=std::move(current.value.source);r.id=id.value;auto appended=common.append_fact({id.value,political_governance_continue_kind,political_governance_continuation_module});if(!appended.ok)return {false,{},appended.error};if(!state.continuations.insert(id.value,std::move(r)))return {false,{},common_failure("DuplicateGovernanceContinuation",id.value).error};return id;
}
}
